  waqfRules: [{"id": 1, "symbol": "O", "description": "جہاں بات پوری ہو جاتی ہے ، وہاں چھوٹا سا دائرہ بنادیتے ہیں۔ یہ حقیقت میں گول ’’ت‘‘ ہے۔ جو بصورت ’’ۃ ‘‘ لکھی جاتی ہے اور یہ وقفِ تام کی علامت ہے یعنی اس پر ٹھہرنا چاہئے، اب ’’ۃ ‘‘ تو نہیں لکھی جاتی البتہ چھوٹا سا دائرہ بنادیا جاتا ہے ،اسی کو آیت کہتے ہیں۔"}, {"id": 2, "symbol": "م", "description": "یہ علامت وقفِ لازم کی ہے اس پر ضرور ٹھہرنا چاہیے، اگر نہ ٹھہرا جائے تو احتمال ہے کہ مطلب کچھ کاکچھ ہو جائے۔ اس کی مثال اردو میں یوں سمجھنی چاہیے کہ مثلاً کسی کو یہ کہنا ہو کہ ’’ اٹھو، مت بیٹھو‘‘ جس میں اٹھنے کا امر اور بیٹھنے کی نہی ہے تو ’’اٹھو‘‘پر ٹھہرنا لازم ہے، اگرنہ ٹھہرا جائے تو ’’اٹھو مت بیٹھو‘‘ ہو جائے گا۔ جس میں اٹھنے کی نہی اور بیٹھنے کے امر کا احتمال ہے اور یہ قائل کے مطلب کے خلاف ہو جائے گا۔"}, {"id": 3, "symbol": "ط", "description": "یہ وقفِ مطلق کی علامت ہے اس پر ٹھہرنا چاہیے مگر یہ علامت وہاں ہوتی ہے جہاں مطلب تمام نہیں ہوتا اور بات کہنے والا ابھی کچھ اور کہنا چاہتا ہے ۔"}, {"id": 4, "symbol": "ج", "description": "یہ وقفِ جائز کی علامت ہے یہاں ٹھہرنا بہتر اور نہ ٹھہرنا جائز ہے ۔"}, {"id": 5, "symbol": "ز", "description": "یہ وقفِ مجوز کی علامت ہے یہاں نہ ٹھہرنا بہتر ہے ۔"}, {"id": 6, "symbol": "ص", "description": "یہ وقفِ مرخص کی علامت ہے۔یہاں ملاکرپڑھناچاہئے،لیکن اگر کوئی تھک کر ٹھہر جائے تو رخصت ہے ۔ معلوم رہے کہ ’’ ص‘‘ پر ملا کر پڑھنا ’’ز‘‘ کی نسبت زیادہ ترجیح رکھتا ہے ۔"}, {"id": 7, "symbol": "صلے", "description": "یہ ’’ اَلْوَصْلُ اَوْلٰی ‘‘کا اختصار ہے ،یعنی یہاں ملا کر پڑھنا بہتر ہے ۔"}, {"id": 8, "symbol": "ق", "description": "یہ ’’قِیْلَ عَلَیْہِ الْوَقْفْ‘‘کاخلاصہ ہے یہاں ٹھہرنا نہیں چاہیے۔"}, {"id": 9, "symbol": "صل", "description": "یہ ’’قَدْ یُوْصَلُ‘‘ کی علامت ہے یعنی یہاں کبھی ٹھہرا بھی جاتا ہے اور کبھی نہیں بھی ٹھہراجاتا، لیکن ٹھہرنا بہتر ہے۔"}, {"id": 10, "symbol": "قف", "description": "یہ لفظِ ’’قِفْ‘‘ہے جس کے معنی ہیں ’’ٹھہرجاؤ ‘‘اور یہ علامت وہاں استعمال کی جاتی ہے جہاں پڑھنے والے کے ملا کر پڑھنے کااحتمال ہو۔"}, {"id": 11, "symbol": "س یا سکتہ", "description": "یہ دونوںسکتہ کی علامات ہیں یہاں اس طرح ٹھہرنا چاہئے کہ آوازٹوٹ جائے مگر سانس نہ ٹوٹنے پائے۔"}, {"id": 12, "symbol": "وقفۃ", "description": "یہ بھی سکتہ کی علامت ہے البتہ یہاں ماقبل دونوں علامات’’س یا سکتہ‘‘کی نسبت زیادہ ٹھہرنا چاہیے اور سانس بھی نہ ٹوٹے۔سکتہ اور وقفہ میں یہی فرق ہے کہ سکتہ میں کم اور وقفہ میں زیادہ ٹھہرا جاتا ہے۔"}, {"id": 13, "symbol": "لا", "description": "’’لا‘‘کے معنی ’’نہیں‘‘ہیں،یہ علامت کہیں آیت کے اوپر استعمال کی جاتی ہے اور کہیں عبارت کے اندر۔ عبارت کے اندر ہو تو ہر گز نہیں ٹھہرنا چاہئے البتہ آیت کے اوپر ہو تواس پرٹھہرنے یانہ ٹھہرنے میں اختلاف ہے لیکن ٹھہرا جائے یا نہ ٹھہرا جائے اس سے مطلب میں خلل واقع نہیں ہوتا۔"}, {"id": 14, "symbol": "ك", "description": "یہ ’’کَذٰلِکَ‘‘ کی علامت ہے یعنی اس سے پہلے جوعلامتِ وقف ہے یہاں بھی وہی سمجھی جائے۔"}, {"id": 15, "symbol": "۰۰۰  ۰۰۰", "description": "اگرکوئی عبارت اِن تین تین نقطوں کے درمیان ہوتوپڑھنے والے کواختیار ہے کہ پہلے تین نقطوں پروقف کرکے دو سرے تین نقطوں پروقف نہ کرے یا پہلے تین نقطوں پروقف نہ کرکے دوسرے تین نقطوں پر وقف کرے۔ اس قسم کی عبارت کو معانقہ یا مراقبہ کہتے ہیں۔"}],
